# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import triton
import triton.language as tl


@triton.jit
def _logit_kernel(
    x_ptr, N, eps, HAS_EPS: tl.constexpr, total_blocks, BLOCK: tl.constexpr
):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    # Grid-stride (persistent) in-place loop. Two constraints shape this design:
    #   1. A one-block-per-program grid with in-place load+store to the same
    #      storage miscompiles program block 0 on this flagtree 0.6.1+ascend3.5
    #      / CANN 9.0.0 toolchain. The grid-stride form avoids that hazard, but
    #      only when the launched program count stays <= the physical vector
    #      core count (confirmed via debug jobs: pg<=num_vectorcore is correct,
    #      pg slightly above it corrupts data). We therefore cap the grid at
    #      num_vectorcore so each program maps to a distinct core.
    #   2. The op is throughput/compute-bound on the transcendental, so a larger
    #      BLOCK (more elements per iteration) is substantially faster than the
    #      default 1024.
    for blk in range(pid, total_blocks, nprog):
        offs = blk * BLOCK + tl.arange(0, BLOCK)
        mask = offs < N
        x = tl.load(x_ptr + offs, mask=mask)
        xf = x.to(tl.float32)
        if HAS_EPS:
            lo = eps
            hi = 1.0 - eps
            xf = tl.minimum(tl.maximum(xf, lo), hi)
        res = tl.log(xf / (1.0 - xf))
        tl.store(x_ptr + offs, res.to(x.dtype), mask=mask)


def _num_vectorcore(device):
    try:
        from triton.runtime import driver

        props = driver.active.utils.get_device_properties(device)
        return int(props["num_vectorcore"])
    except Exception:
        return 0


def logit_(self, eps=None):
    N = self.numel()
    if N == 0:
        return self

    needs_copy_back = not self.is_contiguous()
    buf = self if not needs_copy_back else self.contiguous()
    flat = buf.view(-1)

    # Throughput-bound: a larger BLOCK amortizes the transcendental loop. The
    # Ascend unified buffer caps the per-block working set (everything upcasts
    # to FP32 internally), so FP32 inputs (4 bytes) tolerate a smaller BLOCK
    # than 16-bit inputs (2 bytes). Measured UB ceilings on this toolchain:
    # FP32 overflows at 8192 (8064 is the fastest safe value), 16-bit overflows
    # at 10240 (9216 is the fastest safe value). These were the fastest
    # correct BLOCKs across a sweep on billion-element tensors.
    BLOCK = 8064 if buf.element_size() >= 4 else 9216
    total_blocks = triton.cdiv(N, BLOCK)

    # Persistent grid capped at one program per vector core (queried at runtime,
    # not a hard-coded physical-core constant), and never more than the work.
    nvc = _num_vectorcore(flat.device)
    if nvc <= 0:
        nvc = 40
    nprog = min(total_blocks, nvc)
    grid = (nprog,)

    has_eps = eps is not None
    eps_val = float(eps) if has_eps else 0.0

    _logit_kernel[grid](flat, N, eps_val, has_eps, total_blocks, BLOCK)

    if needs_copy_back:
        self.copy_(buf.view_as(self))
    return self
